package main

import (
	"encoding/json"
	"html/template"
	"net/http"
	"net/url"
	"strings"
	"time"
	"github.com/marellasunil/FleetAMP/internal/configs"
	"github.com/marellasunil/FleetAMP/internal/distributions"
	"github.com/marellasunil/FleetAMP/internal/groups"
	"github.com/marellasunil/FleetAMP/internal/storage"
)

type distributionConfigureView struct{Page string;Distribution *distributions.Distribution;Groups []*groups.Group;Sections []configs.SectionDefinition;Previews []*distributions.DeploymentPreview;Message,Error string}
const distributionConfigureHTML=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configure Distribution · FleetAMP</title><style>`+controlPlaneCSS+detailCSS+`.configure-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,.7fr);gap:16px}.section-editor{display:grid;gap:12px}.policy-summary{display:grid;grid-template-columns:1fr 1fr;gap:10px}@media(max-width:1050px){.configure-layout,.policy-summary{grid-template-columns:1fr}}</style></head><body><div class="shell">`+sideNav+`<main class="main"><header class="top"><div><div class="crumb">FleetAMP / Lifecycle / Distributions / Configure</div><div class="pagetitle">Configure {{.Distribution.Name}}</div><div class="subtitle">Create an immutable, validated configuration preview for an authorized group.</div></div><div class="topactions"><a class="btn" href="/collector-distributions">Back to catalog</a></div></header><div class="content">{{if .Message}}<div class="notice">{{.Message}}</div>{{end}}{{if .Error}}<div class="configerror" role="alert">{{.Error}}</div>{{end}}<div class="configure-layout"><section class="card"><div class="cardhead"><div><div class="cardtitle">Group configuration overlay</div><div class="cardsub">Only sections permitted by the published distribution are editable.</div></div></div><div class="cardbody"><form method="post"><label>Authorized group<select class="select" name="group_id" required><option value="">Select group</option>{{range .Groups}}<option value="{{.ID}}">{{.Name}}</option>{{end}}</select></label><div class="policy-summary" style="margin-top:14px"><div class="managed-field"><strong>Organization-managed</strong><div class="chips">{{range .Distribution.LockedSections}}<span class="chip">{{.}}</span>{{end}}</div></div><div class="managed-field"><strong>Group-editable</strong><div class="chips">{{range .Distribution.EditableSections}}<span class="chip">{{.}}</span>{{end}}</div></div></div><div class="section-editor" style="margin-top:14px">{{range .Sections}}<label><strong>{{.Title}}</strong><span class="tiny">{{.Description}}</span><textarea class="input code" name="section_{{.Key}}" rows="7" placeholder="Enter the {{.Title}} YAML fragment"></textarea></label>{{else}}<div class="empty">This distribution exposes no editable configuration sections.</div>{{end}}</div><div class="notice" style="margin-top:14px">FleetAMP composes the submitted sections, validates YAML and pipeline references, and freezes the distribution hash, group and resulting configuration. No deployment occurs.</div><div class="detailactions"><button class="btn primary" type="submit">Validate &amp; save immutable preview</button></div></form></div></section><aside class="card"><div class="cardhead"><div><div class="cardtitle">Distribution evidence</div><div class="cardsub">{{.Distribution.CollectorVersion}} · {{.Distribution.SourceRef}}</div></div></div><div class="cardbody"><div class="tiny code">{{.Distribution.SpecHash}}</div><div class="chips"><span class="chip">{{len .Distribution.Components.Receivers}} receivers</span><span class="chip">{{len .Distribution.Components.Processors}} processors</span><span class="chip">{{len .Distribution.Components.Exporters}} exporters</span></div></div></aside></div><section class="card" style="margin-top:16px"><div class="cardhead"><div><div class="cardtitle">Immutable previews</div><div class="cardsub">Validated deployment evidence; approval handoff is the next stage.</div></div></div>{{if .Previews}}<div style="overflow:auto"><table><thead><tr><th>Group</th><th>Distribution</th><th>Content evidence</th><th>Prepared</th><th>Status</th></tr></thead><tbody>{{range .Previews}}<tr><td>{{.GroupName}}<div class="tiny code">{{.GroupID}}</div></td><td class="code">{{.DistributionSpecHash}}</td><td class="code">{{.ContentHash}}</td><td>{{.PreparedBy}}<div class="tiny">{{.CreatedAt}}</div></td><td><span class="badge ok">Validated</span></td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty">No previews have been saved for this distribution.</div>{{end}}</section></div></main></div></body></html>`
var distributionConfigurePage=template.Must(template.New("distribution-configure").Parse(distributionConfigureHTML))

func registerDistributionPreviewRoutes(mux *http.ServeMux,distributionStore storage.DistributionStore,previewStore storage.DistributionPreviewStore,groupStore storage.GroupStore,validator *configs.Validator,auth *authManager){
	mux.HandleFunc("/collector-distributions/configure",func(w http.ResponseWriter,r *http.Request){
		distribution,err:=distributionStore.Get(r.Context(),strings.TrimSpace(r.URL.Query().Get("id")));if err!=nil{http.NotFound(w,r);return}
		allGroups,err:=groupStore.List(r.Context());if err!=nil{internalServerError(w,err);return};visible:=groupsVisibleToUser(r.Context(),auth,currentUsername(auth,r),currentRole(auth,r),allGroups)
		if r.Method==http.MethodPost{if err:=r.ParseForm();err!=nil{http.Error(w,"invalid form",400);return};groupID:=strings.TrimSpace(r.FormValue("group_id"));var selected *groups.Group;for _,group:=range visible{if group.ID==groupID{selected=group;break}};if selected==nil{http.Error(w,"forbidden: select a group assigned to your account",http.StatusForbidden);return};sections:=map[string]string{};allowed:=map[string]bool{};for _,key:=range distribution.EditableSections{allowed[key]=true};for _,definition:=range configs.ConfigurationSectionDefinitions{value:=strings.TrimSpace(r.FormValue("section_"+definition.Key));if value!=""{if !allowed[definition.Key]{http.Error(w,"configuration section is organization-managed: "+definition.Title,http.StatusForbidden);return};sections[definition.Key]=value}};content,composeErr:=configs.ComposeConfigurationSections("",sections);if composeErr!=nil{renderDistributionConfigure(w,r,distribution,visible,previewStore,"",composeErr.Error());return};validation:=validator.Validate(r.Context(),content);if !validation.Valid{renderDistributionConfigure(w,r,distribution,visible,previewStore,"",validation.Error);return};evidence,_:=json.Marshal(validation);preview,previewErr:=distributions.NewDeploymentPreview(distribution,selected.ID,selected.Name,sections,content,string(evidence),currentUsername(auth,r),time.Now());if previewErr==nil{previewErr=previewStore.Create(r.Context(),preview)};if previewErr!=nil{renderDistributionConfigure(w,r,distribution,visible,previewStore,"",previewErr.Error());return};http.Redirect(w,r,"/collector-distributions/configure?id="+url.QueryEscape(distribution.ID)+"&message="+url.QueryEscape("Validated immutable preview saved. No deployment was performed."),http.StatusSeeOther);return}
		if r.Method!=http.MethodGet{http.Error(w,"method not allowed",405);return};renderDistributionConfigure(w,r,distribution,visible,previewStore,r.URL.Query().Get("message"),"")
	})
}
func renderDistributionConfigure(w http.ResponseWriter,r *http.Request,d *distributions.Distribution,visible []*groups.Group,store storage.DistributionPreviewStore,message,pageError string){items,err:=store.List(r.Context(),200);if err!=nil{internalServerError(w,err);return};filtered:=items[:0];for _,item:=range items{if item.DistributionID==d.ID{for _,group:=range visible{if group.ID==item.GroupID{filtered=append(filtered,item);break}}}};definitions:=[]configs.SectionDefinition{};allowed:=map[string]bool{};for _,key:=range d.EditableSections{allowed[key]=true};for _,definition:=range configs.ConfigurationSectionDefinitions{if allowed[definition.Key]{definitions=append(definitions,definition)}};w.Header().Set("Content-Type","text/html; charset=utf-8");if err:=distributionConfigurePage.Execute(w,distributionConfigureView{Page:"collector-distributions",Distribution:d,Groups:visible,Sections:definitions,Previews:filtered,Message:message,Error:pageError});err!=nil{internalServerError(w,err)}}
